"""Standalone SVG/JS hover charts embedded in the Streamlit results iframe.
Chart works without third-party JS libraries and uses the SAME OHLCV data as scan.
"""
from __future__ import annotations
import json


def render_results(records:list[dict], timeframe:str, benchmark:str) -> str:
    raw=json.dumps([{**r,'_row_id':str(i)} for i,r in enumerate(records)],ensure_ascii=True,allow_nan=False).replace('</','<\\/')
    tf=json.dumps(timeframe); bench=json.dumps(benchmark)
    return r'''<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
:root{--bg:#0b1018;--panel:#131e2b;--border:#263647;--ink:#e7eff7;--muted:#a1b2c4;--green:#27d08b;--red:#f06b76;--gold:#eabf65}
*{box-sizing:border-box}html,body{margin:0;background:transparent;color:var(--ink);font:14px/1.45 -apple-system,BlinkMacSystemFont,Inter,Segoe UI,Arial,sans-serif}button,input,select{font:inherit;color:var(--ink)}
.toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:0 0 15px} .search{min-width:220px;padding:10px 12px;border:1px solid #354c63;background:#172432;color:#fff;border-radius:9px;outline:none}.search::placeholder{color:#a9b8c8} .hint{color:var(--muted);font-size:12px} .count{font-weight:700;color:#dce7f1;padding-right:12px}
.tablewrap{overflow-x:auto;border:1px solid #29394b;border-radius:12px;background:#121b27}table{width:100%;border-collapse:collapse;white-space:nowrap;font-variant-numeric:tabular-nums;}th{background:#192536;color:#b6c7da;position:sticky;top:0;text-align:right;font-size:12px;letter-spacing:.01em;font-weight:650;padding:13px 12px;cursor:pointer;border-bottom:1px solid #3a4b5e}td{padding:12px;border-bottom:1px solid #243343;text-align:right;color:#d9e6f1}td:first-child,th:first-child{text-align:left;position:sticky;left:0;background:#152131;z-index:1;}th:first-child{z-index:2;background:#1a2838}tr:hover td{background:#1a2a3a}tr:hover td:first-child{background:#203043}tr:last-child td{border-bottom:0}a{color:#e9f4ff;text-decoration:none}a:hover{color:#4be8a5}.ticker{font-weight:800;letter-spacing:.02em;color:#fff;border-bottom:1px dashed #7c91a3;cursor:zoom-in}.ticker:hover{color:#36e6a2;border-bottom-color:#36e6a2}.pill{display:inline-block;font-weight:700;font-size:11px;border-radius:5px;padding:4px 6px}.green{color:#32dc98;background:#103f34}.gold{color:#f2c978;background:#3b311e}.neg{color:#fb858f}.pos{color:#36d59a}.dim{color:#778fa4} .empty{padding:36px;text-align:center;color:#9fb2c6}
#popover{display:none;position:fixed;z-index:99999;width:min(790px,calc(100vw - 25px));pointer-events:none;box-shadow:0 20px 70px #000c;border-radius:14px;background:#0d1722;border:1px solid #456078;padding:0;overflow:hidden}#popover.pinned{pointer-events:auto}#pophead{display:flex;align-items:center;gap:11px;padding:12px 16px;background:#172637;border-bottom:1px solid #33495f}#pophead strong{font-size:18px}#pophead small{color:#a5b8ca}#pophead button{margin-left:auto;border:1px solid #465d73;border-radius:7px;background:#213348;cursor:pointer;padding:5px 9px}#popbody{padding:13px 14px 10px;}#chart svg{width:100%;height:auto;display:block}.stats{display:flex;gap:8px;flex-wrap:wrap;margin:4px 0 6px}.stats span{border:1px solid #354a5e;padding:4px 7px;border-radius:5px;color:#c7d6e5;font-size:12px}.popupfoot{font-size:11px;color:#8ea3b7;padding:0 14px 10px}.topguide{color:#bccadb;margin-bottom:5px} .legend{color:#b3c4d5;font-size:11px;margin-top:5px}
@media(max-width:750px){.tablewrap{font-size:12px}th,td{padding:8px 7px}#popover{width:calc(100vw - 15px)}#pophead strong{font-size:15px}}
</style></head><body>
<div class="toolbar"><input class="search" id="search" placeholder="Filter tickers / status..."><span class="count" id="count"></span><span class="hint">Hover on ticker = annotated Darvas / weekly pullback chart · Click = pin chart · Click headings = sort</span></div>
<div class="tablewrap"><table><thead id="thead"></thead><tbody id="rows"></tbody></table></div>
<div id="popover"><div id="pophead"><strong id="poptitle"></strong><small id="popsubtitle"></small><button id="close">Close ✕</button></div><div id="popbody"><div class="stats" id="stats"></div><div id="chart"></div><div class="legend">Green/red = candles · amber = EMA20 for Darvas/VCP or 20W EMA/SMA for pullbacks · dotted cyan = pullback breakout reference · green circle = first MA touch · dashed green = box resistance · dashed red = box support · yellow dashed = earlier swing high (reference, not box) · violet dotted = older base high for VCP (not entry pivot) · cyan = RS vs benchmark (normalized to 100)</div></div><div class="popupfoot">Prices: completed adjusted OHLCV bars; chart uses detected box and signal date; the VCP rectangle is the FINAL tight contraction. Older reference highs are not entry pivots. RS line is relative, not a percentage return.</div></div>
<script>
const DATA=__DATA__, TIMEFRAME=__TF__, BENCH=__BENCH__;
const COLS=[['ticker','Ticker'],['exchange','Exchange'],['pattern','Pattern'],['status','Setup'],['signal_date','Signal'],['close','Signal close'],['current_close','Last close'],['signal_age_bars','Age (bars)'],['extension_from_entry_pct','Ext. %'],['breakout_date','Prior BO'],['weeks_after_breakout','Uptrend w'],['advance_pct','Impulse %'],['ma_distance_pct','vs MA %'],['box_top','Box high'],['box_bottom','Box low'],['earlier_pivot','Prior pivot'],['major_base_top','Base high'],['box_pct','Box %'],['contraction_ratio','Contr. ratio'],['atr_ratio','TR ratio'],['volume_ratio','Vol ratio'],['bars','Bars'],['distance_pct','Break / Gap %'],['risk_pct','SL risk %'],['rs_3m','RS 3M %'],['rs_percentile','RS rank'],['rs_new_high','RS 52w H'],['sctr','SCTR']];
let ascending=false,sortkey='rs_3m', pinned=null,cur=null;
const fmt=(x,dec=2)=> x==null || Number.isNaN(+x) ? '—' : (+x).toLocaleString('en-US',{maximumFractionDigits:dec,minimumFractionDigits:dec});
const shade=x=> x==null?'dim':+x>=0?'pos':'neg';
const esc=s=>String(s==null?'':s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
function cell(r,k){const v=r[k];if(k==='ticker')return `<span class="ticker" tabindex="0" data-symbol="${esc(r._row_id)}">${esc(v)}</span>`;if(k==='exchange')return esc(v||'—');if(k==='status')return `<span class="pill ${['BREAKOUT','BOUNCE CONFIRMED'].includes(v)?'green':'gold'}">${esc(v)}</span>`;if(k==='rs_new_high')return v?'✓':'—';if(k==='signal_date'||k==='breakout_date')return esc(v);if(v==null)return '<span class="dim">—</span>';if(['rs_3m','distance_pct','extension_from_entry_pct','advance_pct','ma_distance_pct'].includes(k))return `<span class="${shade(v)}">${fmt(v)}${k==='rs_3m'?'%':''}</span>`;if(k==='bars'||k==='signal_age_bars'||k==='weeks_after_breakout')return esc(v);return fmt(v,k==='rs_percentile'||k==='sctr'?1:2);}
function table(){let s=document.getElementById('search').value.trim().toUpperCase();let a=DATA.filter(x=>!s||(x.ticker+' '+x.pattern+' '+x.status).toUpperCase().includes(s));a.sort((x,y)=>{let m=x[sortkey],n=y[sortkey];if(m==null)return 1;if(n==null)return -1;let cmp=typeof m==='number'&&typeof n==='number'?m-n:String(m).localeCompare(String(n));return ascending?cmp:-cmp});document.getElementById('count').textContent=a.length+' results';document.getElementById('rows').innerHTML=a.length?a.map(r=>'<tr>'+COLS.map(([k])=>`<td>${cell(r,k)}</td>`).join('')+'</tr>').join(''):'<tr><td colspan="25" class="empty">No results for this text filter</td></tr>';document.querySelectorAll('.ticker').forEach(t=>{let r=DATA.find(d=>d._row_id===t.dataset.symbol);t.onmouseenter=e=>show(r,e,false);t.onmousemove=e=>position(e);t.onmouseleave=e=>{if(!pinned)hide()};t.onclick=e=>{e.stopPropagation();if(pinned===r._row_id){pinned=null;hide()}else{pinned=r._row_id;show(r,e,true)}};t.onfocus=e=>show(r,{clientX:180,clientY:140},false);});}
function init(){document.getElementById('thead').innerHTML='<tr>'+COLS.map(([k,v])=>`<th data-key="${k}" title="Sort by ${esc(v)}">${esc(v)} ▾</th>`).join('')+'</tr>';document.querySelectorAll('th').forEach(t=>t.onclick=()=>{let k=t.dataset.key;ascending=k===sortkey?!ascending:false;sortkey=k;table()});document.getElementById('search').oninput=table;document.getElementById('close').onclick=()=>{pinned=null;hide()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){pinned=null;hide()}});table()}
function hide(){document.getElementById('popover').style.display='none';document.getElementById('popover').classList.remove('pinned');cur=null}
function position(e){if(pinned)return;let p=document.getElementById('popover');if(p.style.display!=='block')return;let w=p.offsetWidth,h=p.offsetHeight, W=innerWidth,H=innerHeight;let x=e.clientX+20,y=e.clientY+12;if(x+w>W-8)x=Math.max(8,e.clientX-w-18);if(y+h>H-5)y=Math.max(5,H-h-8);p.style.left=x+'px';p.style.top=y+'px'}
function show(r,e,pin){if(!r||pinned&&pinned!==r._row_id&&!pin)return;const p=document.getElementById('popover');if(cur!==r._row_id){cur=r._row_id;document.getElementById('poptitle').textContent=r.ticker;document.getElementById('popsubtitle').textContent=TIMEFRAME+' • '+r.pattern+' • '+r.status+' • '+r.signal_date;document.getElementById('stats').innerHTML=(r.pattern.startsWith('First pullback')?[`MA ${r.ma_kind}`,`Breakout ${r.breakout_date}`,`Impulse +${fmt(r.advance_pct)}%`,`Uptrend ${r.weeks_after_breakout} w`,`Low vs MA ${fmt(r.distance_to_ma_low_pct)}%`,`Touch ${r.touch_date||'pending'}`,`Trigger above ${fmt(r.entry)}`,`Stop below ${fmt(r.stop)}`,`Risk ${fmt(r.risk_pct)}%`,`RS / ${BENCH}: ${fmt(r.rs_3m)}%`]:[`Box ${fmt(r.box_bottom)} – ${fmt(r.box_top)}`,`Entry ${fmt(r.entry)}`,`Stop ${fmt(r.stop)}`,`Risk ${fmt(r.risk_pct)}%`,`Last ${fmt(r.current_close)}`,`Age ${r.signal_age_bars} bars`,`Ext. ${fmt(r.extension_from_entry_pct)}%`, ...(r.pattern.startsWith('VCP')?[`Contraction ${fmt(r.contraction_ratio,2)}`,`Vol ratio ${fmt(r.volume_ratio,2)}`]:[]),`RS / ${BENCH}: ${fmt(r.rs_3m)}%`]).map(x=>`<span>${esc(x)}</span>`).join('');document.getElementById('chart').innerHTML=chartSVG(r)}p.style.display='block';p.classList.toggle('pinned',Boolean(pin||pinned));if(pin){p.style.left=Math.max(7,Math.round((innerWidth-p.offsetWidth)/2))+'px';p.style.top=Math.max(4,Math.round((innerHeight-p.offsetHeight)/2))+'px'}else position(e)}
function chartSVG(r){let rows=(r.chart||[]).slice(-82),N=rows.length;if(!N)return '<p>Chart data unavailable.</p>';let W=736,H=432,L=54,R=58,T=16,bottom=272,volT=286,volB=329,rsT=358,rsB=410,plotW=W-L-R;let isPullback=r.pattern.startsWith('First pullback');let min=Math.min(...rows.map(x=>x.l),...(Number.isFinite(r.box_bottom)?[r.box_bottom]:[]))*.98,max=Math.max(...rows.map(x=>x.h),...(Number.isFinite(r.box_top)?[r.box_top]:[]))*1.02;if(max<=min)max=min+1;let py=v=>bottom-(v-min)/(max-min)*(bottom-T),px=i=>L+(i+.5)*plotW/N;
let out=[`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg"><rect width="${W}" height="${H}" fill="#0b1621" rx="7"/>`];
for(let j=0;j<=5;j++){let p=min+(max-min)*j/5,y=py(p);out.push(`<line x1="${L}" y1="${y.toFixed(2)}" x2="${W-R}" y2="${y.toFixed(2)}" stroke="#243649" stroke-width=".7"/><text x="${W-R+7}" y="${(y+4).toFixed(2)}" fill="#93a9bf" font-size="11">${fmt(p)}</text>`)}
// Box is only the consolidation window preceding signal, shaded rather than full-width.
let ix=rows.findIndex(x=>x.d===r.signal_date);if(ix<0)ix=N-1;let start=rows.findIndex(x=>x.d===r.box_start_date);if(start<0)start=Math.max(0,ix-r.bars);let end=rows.findIndex(x=>x.d===r.box_end_date);if(end<0)end=Math.max(start,ix-1);let x1=px(start)-3,x2=px(end)+3;
if(!isPullback){
let yTop=py(r.box_top),yBot=py(r.box_bottom);
out.push(`<rect x="${x1}" y="${yTop}" width="${Math.max(1,x2-x1)}" height="${yBot-yTop}" fill="${r.pattern.startsWith('VCP')?'#22d3a9':'#d8b064'}" fill-opacity=".13" stroke="${r.pattern.startsWith('VCP')?'#39e3b1':'#e1b760'}" stroke-width="2" stroke-dasharray="5 3"/>`);
for(let [v,c,label] of [[r.box_top,'#29d49b','Resistance'],[r.box_bottom,'#e07179','Support']]){let y=py(v);out.push(`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="${c}" stroke-dasharray="5 5" stroke-opacity=".75"/><text x="${L+7}" y="${y-5}" font-size="10" fill="${c}">${label} ${fmt(v)}</text>`)}
if(r.pattern.startsWith('VCP')&&Number.isFinite(r.major_base_top)&&Math.abs(r.major_base_top-r.box_top)/r.box_top>0.006){let y=py(r.major_base_top);out.push(`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#a98cff" stroke-opacity=".7" stroke-width="1.2" stroke-dasharray="2 6"/><text x="${L+7}" y="${y-5}" fill="#a98cff" font-size="10">Older base top ${fmt(r.major_base_top)}</text>`)}
if(Number.isFinite(r.earlier_pivot)){
 let y=py(r.earlier_pivot);
 out.push(`<line x1="${L+plotW*.24}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#f6d04e" stroke-opacity=".9" stroke-width="1.8" stroke-dasharray="11 3"/><text x="${L+plotW*.27}" y="${y-6}" fill="#f6d04e" font-size="10">Prior pivot ${fmt(r.earlier_pivot)} (reference only)</text>`)
}
}else{
 let bi=rows.findIndex(x=>x.d===r.breakout_date), ti=rows.findIndex(x=>x.d===r.touch_date);
 if(Number.isFinite(r.breakout_level)){
   let by=py(r.breakout_level);
   out.push(`<line x1="${bi>=0?px(bi):L}" x2="${W-R}" y1="${by}" y2="${by}" stroke="#62bbea" stroke-width="1.2" stroke-dasharray="2 5"/><text x="${L+9}" y="${by-5}" fill="#62bbea" font-size="11">Earlier breakout ${fmt(r.breakout_level)}</text>`);
 }
 if(bi>=0){out.push(`<circle cx="${px(bi)}" cy="${py(rows[bi].h)-8}" r="4" fill="#f3d47f"/><text x="${px(bi)+7}" y="${py(rows[bi].h)-11}" fill="#f3d47f" font-size="11">Breakout</text>`)}
 if(ti>=0){out.push(`<circle cx="${px(ti)}" cy="${py(rows[ti].l)+9}" r="6" fill="none" stroke="#2df0a1" stroke-width="2.1"/><text x="${px(ti)+9}" y="${py(rows[ti].l)+22}" fill="#2df0a1" font-size="11">First MA touch</text>`)}
 if(r.status==='BOUNCE CONFIRMED'&&ix>=0){out.push(`<path d="M${px(ix)-7} ${py(rows[ix].h)-17} l7 -10 l7 10" fill="none" stroke="#2df0a1" stroke-width="2"/>`)}
}
const maxVol=Math.max(1,...rows.map(x=>x.v));let bodyW=Math.max(2,Math.min(8,plotW/N*.72));
rows.forEach((p,i)=>{let x=px(i),up=p.c>=p.o,color=up?'#27cb89':'#ed6771',yo=py(p.o),yc=py(p.c);out.push(`<line x1="${x}" y1="${py(p.h)}" x2="${x}" y2="${py(p.l)}" stroke="${color}" stroke-width="1.3"/>`);out.push(`<rect x="${x-bodyW/2}" y="${Math.min(yo,yc)}" width="${bodyW}" height="${Math.max(1.25,Math.abs(yo-yc))}" fill="${color}"/>`);let vh=p.v/maxVol*(volB-volT);out.push(`<rect x="${x-bodyW/2}" y="${volB-vh}" width="${bodyW}" height="${vh}" fill="${color}" opacity=".55"/>`)});
let ema=rows.map((p,i)=>p.ema==null?null:[px(i),py(p.ema)]).filter(x=>x!==null);if(ema.length>1)out.push(`<path d="${ema.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ')}" stroke="#f4bb65" stroke-width="2" fill="none"/>`);
if(r.status==='BREAKOUT'&&ix>=0){out.push(`<circle cx="${px(ix)}" cy="${py(rows[ix].h)-9}" r="4" fill="#2df0a1"/><path d="M${px(ix)-7} ${py(rows[ix].h)-18} l7 -8 l7 8" fill="none" stroke="#2df0a1" stroke-width="1.8"/>`)}
out.push(`<text x="${L}" y="${volT-4}" fill="#98acbe" font-size="11">VOLUME</text><line x1="${L}" y1="${volB+14}" x2="${W-R}" y2="${volB+14}" stroke="#344a5f"/>`);
// RS line is normalised to its first visible observation and corresponds to dates.
let map=new Map((r.rs_dates||[]).map((date,i)=>[date,r.rs_line[i]]));let rs=rows.map((p,i)=>[i,map.get(p.d)]).filter(x=>Number.isFinite(x[1]));
out.push(`<text x="${L}" y="${rsT-5}" fill="#66ccee" font-size="11">RS vs ${esc(BENCH)}</text>`);
if(rs.length>1){let rmin=Math.min(...rs.map(x=>x[1])),rmax=Math.max(...rs.map(x=>x[1]));if(rmax===rmin)rmax=rmin+1;let pts=rs.map(([i,v])=>[px(i),rsB-(v-rmin)/(rmax-rmin)*(rsB-rsT)]);out.push(`<path d="${pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ')}" fill="none" stroke="#67cbe7" stroke-width="2"/><text x="${W-R+7}" y="${rsT+10}" fill="#67cbe7" font-size="11">${fmt(rmax,1)}</text><text x="${W-R+7}" y="${rsB}" fill="#67cbe7" font-size="11">${fmt(rmin,1)}</text>`)}
let tickStep=Math.max(1,Math.round(N/7));for(let i=0;i<N;i+=tickStep)out.push(`<text x="${px(i)}" y="${H-3}" fill="#8398ab" font-size="10" text-anchor="middle">${rows[i].d.slice(5)}</text>`);
out.push('</svg>');return out.join('')}
init();
</script></body></html>'''.replace('__DATA__',raw).replace('__TF__',tf).replace('__BENCH__',bench)
